class Solution:
    def isPrefixString(self, s: str, words: List[str]) -> bool:
        cur = []
        length = 0
        for w in words:
            cur.append(w)
            length += len(w)
            if length == len(s):
                return ''.join(cur) == s
            if length > len(s):
                break
        return False

