class Solution {
public:
    bool isPrefixString(string s, vector<string>& words) {
        string cur;
        for (auto& w : words) {
            cur += w;
            if (cur.size() == s.size()) return cur == s;
            if (cur.size() > s.size()) break;
        }
        return false;
    }
};

