class Solution {
public:
    bool isPrefixString(string s, vector<string>& words) {
        int i = 0, n = s.size();
        for (auto& w : words) {
            for (char c : w) {
                if (i >= n || s[i] != c) return false;
                i++;
            }
            if (i == n) return true;
        }
        return false;
    }
};

