class Solution {
    public boolean isPrefixString(String s, String[] words) {
        int i = 0, n = s.length();
        for (String w : words) {
            for (int j = 0; j < w.length(); j++) {
                if (i >= n || s.charAt(i) != w.charAt(j)) return false;
                i++;
            }
            if (i == n) return true;
        }
        return false;
    }
}

